    if detailTab=="loot" then dropTitle:SetText(MobName(selected).." - Your loot data: "..(own and own[6] or 0)) end
    local top,previousQuality,previousCategory=0,nil,nil
    for i=1,math.max(#drops,#lootRows) do
        local row=drops[i];local control=lootRows[i] or MakeLootRow(i)
        if row then
            local category=Category(row)
            control.rarity:Hide();control.category:Hide()
            if category~=previousCategory then
                control.category:ClearAllPoints();control.category:SetPoint("TOPLEFT",lootCanvas,"TOPLEFT",0,-top);control.category:SetText(category);control.category:Show();top=top+29;previousQuality=nil
            end
            if row.quality~=previousQuality then
                control.rarity:ClearAllPoints();control.rarity:SetPoint("TOPLEFT",lootCanvas,"TOPLEFT",8,-top);control.rarity:SetText(rarities[row.quality] or "Other rarity");control.rarity:Show();top=top+23
            end
            previousQuality=row.quality;previousCategory=category
            control:ClearAllPoints();control:SetPoint("TOPLEFT",lootCanvas,"TOPLEFT",8,-top);top=top+46
