            control.icon:SetTexture(icon or "Interface\\Icons\\INV_Misc_QuestionMark")
            control.name:SetText(row.fullName or name)
            local color=ITEM_QUALITY_COLORS and ITEM_QUALITY_COLORS[quality]
            if color then control.name:SetTextColor(color.r,color.g,color.b) end
            local names={F="Forever sample",G="Community samples",H="Guild samples",C="Classic estimate",S="Skinning estimate",Y="Your samples"}
            local rate=C.Percent(row).."%  ·  "..names[row.source]..(row.variants>1 and " (stat variants)" or "")
            if row.ownWindows and row.source~="Y" then rate=rate..string.format(" | You %.2f%%",100*row.ownHits/row.ownWindows) end
